    cancelStructurePlacement();
    hideSignalPrompt();
    keys.clear();
    resetMouseButtons();
    player.x = 0;
    player.y = 0;
    player.vx = 0;
    player.vy = 0;
    player.radius = 34;
    player.health = 100;
    player.maxHealth = 100;
    player.energy = playerBaseMaxEnergy;
    player.maxEnergy = playerBaseMaxEnergy;
    player.hitCooldown = 0;
    player.hitFlash = 0;
    player.landed = null;
    player.spacecraftInterior = null;
    player.walkCycle = 0;
    cameraRoll = 0;
    gadgetAngle = -0.32;
