      targetCtx.strokeStyle = rgbaColor(245, 255, 255, alpha * fade * 0.28);
      targetCtx.lineWidth = Math.max(0.7, dropletWidth * 0.42);
      targetCtx.lineCap = "round";
      targetCtx.beginPath();
      targetCtx.arc(0, 0, dropletLength * 0.72, seed + t, seed + t + Math.PI * 0.7);
      targetCtx.stroke();
