    targetCtx.moveTo(0, -size);
    targetCtx.lineTo(size * 0.22, -size * 0.22);
    targetCtx.lineTo(size, 0);
    targetCtx.lineTo(size * 0.22, size * 0.22);
    targetCtx.lineTo(0, size);
    targetCtx.lineTo(-size * 0.22, size * 0.22);
    targetCtx.lineTo(-size, 0);
    targetCtx.lineTo(-size * 0.22, -size * 0.22);
